package testdata

import (
	"bytes"
	"encoding/json"
	"fmt"

	"github.com/FreidhYMorales/credenciales-seguras/internal/generate"
	"github.com/FreidhYMorales/credenciales-seguras/internal/validate"
)

// Parameters of the graded pairs. The seeds are recorded in pares.json so the
// valid pairs can be regenerated byte for byte.
const (
	ValidPairs     = 10
	PasswordSeed0  = int64(2026)
	EmailSeed0     = int64(4490)
	PasswordLength = 20

	validEmailFixed = "ana.perez@correo.com"
	validPassFixed  = "Xk9$mTq2#vLw8@RzQe4&"
)

// Build returns the 20 pairs: 10 generated with recorded seeds and 10 authored
// by hand, each with exactly one defective credential.
func Build() ([]Pair, error) {
	pairs := make([]Pair, 0, 20)

	for i := 0; i < ValidPairs; i++ {
		ps := PasswordSeed0 + int64(i)
		es := EmailSeed0 + int64(i)
		p, err := generate.Password(ps, PasswordLength)
		if err != nil {
			return nil, fmt.Errorf("password seed %d: %w", ps, err)
		}
		e, err := generate.Email(es)
		if err != nil {
			return nil, fmt.Errorf("email seed %d: %w", es, err)
		}
		seedP, seedE := ps, es
		pairs = append(pairs, Pair{
			ID:               i + 1,
			Email:            e.Valor,
			Password:         p.Valor,
			EmailEsperado:    true,
			PasswordEsperado: true,
			SeedEmail:        &seedE,
			SeedPassword:     &seedP,
		})
	}

	// Authored invalid passwords; the email stays valid and fixed.
	invalidPasswords := []struct {
		value string
		rule  string
	}{
		{"Abc123!", "P1"},                // too short
		{"Xk9mTq2vLw8RzQe4NbA", "P5"},    // no special
		{"Xk$mTq#vLw@RzQe&NbA", "P4"},    // no digit
		{"xk9$mtq2#vlw8@rzqe4&", "P2"},   // no uppercase
		{"XK9$MTQ2#VLW8@RZQE4&", "P3"},   // no lowercase
		{"Xk9$mTq2#vLw8@RzQaaa", "P6"},   // triple repetition
		{"Xk9$mTq2#vLw8@RzQabcd", "P7"},  // ascending sequence
		{"Xk9$mTq2#vLw8@password", "P8"}, // forbidden word
	}
	for i, c := range invalidPasswords {
		rule := c.rule
		pairs = append(pairs, Pair{
			ID:               ValidPairs + i + 1,
			Email:            validEmailFixed,
			Password:         c.value,
			EmailEsperado:    true,
			PasswordEsperado: false,
			ReglaFallida:     &rule,
		})
	}

	// Authored invalid emails; the password stays valid and fixed.
	invalidEmails := []struct {
		value string
		rule  string
	}{
		{"ana..perez@correo.com", "C2"}, // double dot in the local part
		{"ana.perez@correo.c", "C5"},    // one-letter TLD
	}
	for i, c := range invalidEmails {
		rule := c.rule
		pairs = append(pairs, Pair{
			ID:               ValidPairs + len(invalidPasswords) + i + 1,
			Email:            c.value,
			Password:         validPassFixed,
			EmailEsperado:    false,
			PasswordEsperado: true,
			ReglaFallida:     &rule,
		})
	}

	return pairs, nil
}

// Encode renders the pairs exactly as pares.json stores them: two-space
// indentation, no HTML escaping, trailing newline.
func Encode(pairs []Pair) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(pairs); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// Verify asserts that every pair produces the verdict the file claims, and that
// the named rule is the one that fails.
func Verify(pairs []Pair) error {
	for _, p := range pairs {
		er := validate.EmailReport(p.Email)
		pr := validate.PasswordReport(p.Password)
		if er.Valido != p.EmailEsperado {
			return fmt.Errorf("par %d: correo %q válido=%v, esperado=%v", p.ID, p.Email, er.Valido, p.EmailEsperado)
		}
		if pr.Valido != p.PasswordEsperado {
			return fmt.Errorf("par %d: contraseña %q válida=%v, esperado=%v", p.ID, p.Password, pr.Valido, p.PasswordEsperado)
		}
		if p.ReglaFallida == nil {
			continue
		}
		if !fails(pr.Reglas, *p.ReglaFallida) && !fails(er.Reglas, *p.ReglaFallida) {
			return fmt.Errorf("par %d: la regla %s no falla", p.ID, *p.ReglaFallida)
		}
	}
	return nil
}

func fails(rs []validate.RuleResult, id string) bool {
	for _, r := range rs {
		if r.ID == id && r.Evaluado && !r.OK {
			return true
		}
	}
	return false
}
